import java.io.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static long nextLong() throws IOException {
        int c = skipSpaces();
        boolean negative = c == '-';
        if (negative) c = read();
        long value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = read();
        }
        return negative ? -value : value;
    }

    private static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long inc = nextLong(), dec = nextLong();
        long[] a = new long[n];
        long lo = Long.MAX_VALUE, sum = 0;
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
            lo = Math.min(lo, a[i]);
            sum += a[i];
        }
        long hi = sum / n;
        // Binary search the largest T whose shortfall (receptions needed) is covered by the surplus.
        while (lo < hi) {
            long mid = (lo + hi + 1) / 2, need = 0, supply = 0;
            for (long v : a) {
                if (v < mid) need += (mid - v + inc - 1) / inc;
                else supply += (v - mid) / dec;
            }
            if (supply >= need) lo = mid;
            else hi = mid - 1;
        }
        System.out.println(lo);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	token := next()
	negative := len(token) > 0 && token[0] == '-'
	if negative {
		token = token[1:]
	}
	value := 0
	for _, c := range token {
		value = value*10 + int(c-'0')
	}
	if negative {
		return -value
	}
	return value
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, inc, dec := nextInt(), nextInt(), nextInt()
	a := make([]int, n)
	sum := 0
	for i := range a {
		a[i] = nextInt()
		sum += a[i]
	}
	lo, hi := slices.Min(a), sum/n
	// Binary search the largest T whose shortfall (receptions needed) is covered by the surplus.
	for lo < hi {
		mid := (lo + hi + 1) / 2
		need, supply := 0, 0
		for _, v := range a {
			if v < mid {
				need += (mid - v + inc - 1) / inc
			} else {
				supply += (v - mid) / dec
			}
		}
		if supply >= need {
			lo = mid
		} else {
			hi = mid - 1
		}
	}
	os.Stdout.WriteString(strconv.Itoa(lo) + "\n")
}
